// 1. Go goroutine 示例
package main

import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup
    for i := 0; i < 100000; i++ {
        wg.Add(1)
        go func(id int) { // 启动 10 万个 goroutine
            defer wg.Done()
            // 每个 goroutine 仅占几 KB 内存
            fmt.Printf("goroutine %d\n", id)
        }(i)
    }
    wg.Wait()
}

// 2. Python asyncio 示例
import asyncio

async def fetch_data(url: str) -> str:
    print(f"Fetching {url}")
    await asyncio.sleep(1)  # 模拟 IO 等待，让出执行权
    return f"Data from {url}"

async def main():
    # 并发执行多个协程
    tasks = [fetch_data(f"http://example.com/{i}") for i in range(10)]
    results = await asyncio.gather(*tasks)
    for r in results:
        print(r)

asyncio.run(main())
// 10 个请求并发执行，总耗时约 1 秒而非 10 秒
